import logging
import os

TRACE = 1
# Logging path that is used as a prefix for log file paths
LOGGING_PATH = "{}{}logs".format(os.getcwd(), os.sep)
UEPC_LOGFILE_NAME = 'ta_ue_uepc_local.log'
active_loggers = []


class UeInfoExtendedFormatter(logging.Formatter):
    """Library developer needs also library-AREA to help in troubleshooting"""

    def __init__(self):
        """Initialize base class with format string containing %(area)s %(alias)s %(ue_id)s"""
        log_fmt = \
            "%(asctime)s | %(levelname)-8s | %(area)-15s %(alias)-10s %(ue_id)-10s | %(message)s /// %(threadName)-11s: %(filename)s(%(lineno)d)"
        super(UeInfoExtendedFormatter, self).__init__(fmt=log_fmt)

    def format(self, record):
        """Ensure log record has .area .ueid .alias to allow for "%(area)s %(alias)s %(ue_id)s" in format string"""
        if not hasattr(record, "alias"):
            record.alias = " "
        if not hasattr(record, "area"):
            record.area = " "
        if not hasattr(record, "ue_id"):
            record.ue_id = ""
        elif record.ue_id and (not record.ue_id.startswith("UE:")):
            record.ue_id = "UE:{}".format(record.ue_id)
        return super(UeInfoExtendedFormatter, self).format(record)


class LoggerAdapter4EmptyExtra(logging.LoggerAdapter):
    """An adapter that fills 'extra' key passed to log records but doesn't overwrite existing extra subkeys."""

    def process(self, msg, kwargs):
        """
        Process the logging message and keyword arguments passed in to
        a logging call to insert contextual information.
        If such information already exists it is not overwritten.
        """
        if 'extra' not in kwargs:
            kwargs["extra"] = self.extra
        else:
            for update_key in self.extra:
                if update_key not in kwargs["extra"]:
                    kwargs["extra"][update_key] = self.extra[update_key]
        return msg, kwargs

    def log(self, level, msg, *args, **kwargs):
        """
        Allow stacking LoggerAdapters.
        Such stacked adapters perform their process() in stacking order
        """
        if self.isEnabledFor(level):
            logger_adapter = self
            max_adapters_nesting_level = 2
            nesting_level = 0
            while isinstance(logger_adapter, logging.LoggerAdapter):
                msg, kwargs = logger_adapter.process(msg, kwargs)
                nesting_level += 1
                if nesting_level > max_adapters_nesting_level:
                    err_msg = "Exceeded nesting level of LoggerAdapters - processing not finished for"
                    self.logger._log(logging.ERROR, "{} msg={}, kwargs={}".format(
                        err_msg, msg, kwargs), args, **kwargs)  # pylint: disable=protected-access
                    return
                logger_adapter = logger_adapter.logger
            self.logger._log(level, msg, args, **kwargs)  # pylint: disable=protected-access


class RemoteAddrAdapter(LoggerAdapter4EmptyExtra):
    """Logger for remote PC"""

    def __init__(self, remote, logger, extra=None):
        """Adapter adding remote address into logs"""
        if extra is None:
            extra = {}
        self.remote = remote
        super(RemoteAddrAdapter, self).__init__(logger, extra=extra)

    def process(self, msg, kwargs):
        """Add remote address into logs"""
        remote = self.remote
        direction = " "
        if 'extra' in kwargs:
            if 'remote' in kwargs['extra']:
                remote = kwargs['extra']['remote']
            if 'direction' in kwargs['extra']:
                direction = kwargs['extra']['direction']
        if remote:
            msg = msg.encode('utf-8')
            msg = "[{:.1}{}] {}".format(direction, remote, msg)
        return super(RemoteAddrAdapter, self).process(msg, kwargs)


def get_logs_dir():
    """
    Returns name of logs folder.
    Will do mmkdir if need
    :return: "logs" or "logs_ue_manager"
    """
    if os.path.exists("logs"):
        return "logs"
    if os.path.exists("logs_ue_manager"):
        return "logs_ue_manager"
    os.mkdir("logs")
    return "logs"


def create_ue_pc_logger():
    """
    Creates logger.
    Able to run on machine without ute_common_abstract_core, for example UE Manager's UE PC
    :return:
    """
    logger_name = "ute_ue.uepc"

    logger_instance = create_logger(logger_name, UEPC_LOGFILE_NAME)
    for hdlr in logger_instance.handlers:
        hdlr.setFormatter(UeInfoExtendedFormatter())
    logger_instance.propagate = True

    return logger_instance


def create_logger(name, log_file, log_level=TRACE, log_format="%(asctime)s %(levelname)-10s: |%(message)s"):
    """
    Creates Logger with file writer
    :param name: Logger name
    :param log_file: Path to logfile. This path is added to LOGGING_PATH variable. Final logfile location is LOGGING_PATH + log_file
    :param log_level: only log records with equal and greater level will be accepted for storage in log
    :param log_format: layout of log file, default is "%(asctime)s %(levelname)-10s: |%(message)s"
    :return: None
    """
    logger = logging.getLogger(name)
    if name not in active_loggers:
        logger.setLevel(log_level)
        logfile_full_path = os.path.join(LOGGING_PATH, log_file)
        _prepare_logs_folder(logfile_full_path)
        setup_new_file_handler(logger_name=name,
                               log_level=log_level,
                               log_filename=logfile_full_path,
                               formatter=logging.Formatter(log_format))

    return logger


def setup_new_file_handler(logger_name, log_level, log_filename, formatter):
    """
    Sets up new file handler for given logger
    :param logger_name: name of logger to which file logger is added
    :param log_level: logging level
    :param log_filename: path to log file
    :param formatter: formatter for file logger
    :return:  logging.FileHandler object
    """
    import logging.handlers
    logger = logging.getLogger(logger_name)
    max_log_file_size = 250 * 1024 * 1024
    cfh = logging.handlers.RotatingFileHandler(os.path.join(get_logs_dir(), log_filename), mode='a', maxBytes=max_log_file_size, backupCount=2)
    cfh.setLevel(log_level)
    cfh.setFormatter(formatter)
    logger.addHandler(cfh)
    return cfh


def _prepare_logs_folder(logfile_full_path):
    """
    Check that log folder exist and creates it if needed.

    :param logfile_full_path: path to log folder
    :return: Nome
    """
    logdir = os.path.dirname(logfile_full_path)
    if not os.path.exists(logdir):
        os.makedirs(logdir)
